head.script:
scwin.unitTest = function() {
    // Init test
    WebSquare.wUnit.start();
    // Test step 1: 1. 샘플파일을 실행하고 전체체크박스를 선택한다. - 1. Run the sample file and select the entire checkbox.
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById($p.id+'grid_emp_list_column1').childNodes[0].click()");
    // Verify 1. 전체 체크박스가 선택되고 하위체크박스가 모두 선택된다. - 1. All check boxes are selected and all lower check boxes are selected.
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getDomById($p.id+'grid_emp_list_column1').childNodes[0].checked", "true");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('grid_emp_list_cell_0_0').childNodes[0].checked", "true");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('grid_emp_list_cell_1_0').childNodes[0].checked", "true");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('grid_emp_list_cell_2_0').childNodes[0].checked", "true");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('grid_emp_list_cell_3_0').childNodes[0].checked", "true");
    WebSquare.wUnit.addCommand("pause", "1000");
    // Test step 2: 2. 초기화버튼을 클릭한다. - 2. Click the Reset button.
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger222').click()");
    // verify 2: 2. header부분의 전체체크박스까지 모두 해제된다. - 2. All check boxes in the header area are cleared.
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getDomById($p.id+'grid_emp_list_column1').childNodes[0].checked", "false");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getDomById($p.id+'grid_emp_list_body_tbody').childNodes[0].style.display=='none'", "true");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getDomById($p.id+'grid_emp_list_body_tbody').childNodes[1].style.display=='none'", "true");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getDomById($p.id+'grid_emp_list_body_tbody').childNodes[2].style.display=='none'", "true");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getDomById($p.id+'grid_emp_list_body_tbody').childNodes[3].style.display=='none'", "true");
    WebSquare.wUnit.addCommand("pause", "1000");
    // Run test
    WebSquare.wUnit.run();
    // Stop test
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    window.pageFunc = {};
    /* 행추가 버튼 클릭 */
    pageFunc.trigger1_onclick = function(e) {
        window.idx = dl_empInfo.insertRow(0);
        // 행추가시 특정 컬럼의 ReadOnly 또는 Disabled 변경한 경우.
        grid_emp_list.setReadOnly("cell", idx, "EMPNO", false);
        grid_emp_list.setDisabled("cell", idx, "SAL", false);
    };
    /* 행삭제 버튼 클릭 */
    pageFunc.trigger2_onclick = function(e) {
        /*
        			window.arrChkIdx = grid_emp_list.getCheckedIndex( "CH_ROW" );
        			// 행삭제시 행추가로 변경된 row의 ReadOnly, Disabled 복구.
        			for( window.i =0 ; i<arrChkIdx.length ; i++ ) {
        				window.idx = arrChkIdx[i];
        				window.rowStatus = grid_emp_list.getRowJSON(idx).rowStatus;
        				if ( rowStatus == "C" ) {
        					grid_emp_list.setReadOnly( "cell" , idx , "EMPNO" , true );
        					grid_emp_list.setDisabled( "cell" , idx , "SAL" , true );
        				}
        			}
        			dl_empInfo.removeRows( arrChkIdx );
        */
        cmCommon.deleteGridRowsRollBack(dl_empInfo, grid_emp_list, "CH_ROW", "EMPNO", "readonly");
        cmCommon.deleteGridRowsRollBack(dl_empInfo, grid_emp_list, "CH_ROW", "SAL", "disabled");
        //dl_empInfo.removeRows( arrChkIdx );
        cmCommon.deleteGridRows(dl_empInfo, grid_emp_list, "CH_ROW");
    };
    pageFunc.trigger222_onclick = function(e) {
        grid_emp_list.initGrid();
        //dl_empInfo.removeAll();
        //dl_empInfo.reform();
    };
    // Function test
    // Created by Sang.Do
    // Created date 17-Jan-2018
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
